#include "pool_destruct_test_fixture.hpp"
using namespace pool_destruct_test;
namespace {
using B=Backing;
void identity_and_lifo(){
    for(unsigned k=0;k<4;++k){
        {Fixture f(k);f.sentinel();auto expected=f.raw.pool;put(expected,0,base_table);reset_image(expected);const auto heaps=f.raw.heaps;f.direct();check(f.raw.pool==expected&&f.raw.heaps==heaps&&f.docs.entered_frees.empty()&&!f.nodes.calls&&!f.docs.other_calls,"empty inline destructor resets three QWORDs and ends at base table without lower frees");}
        {Fixture f(k);f.sentinel();f.raw.count(3,17);put(f.raw.pool,8,B::heap_address());put(f.raw.heaps[0],0,0x1111);put(f.raw.heaps[0],8,0);put(f.raw.heaps[0],16,0x3333);auto expected=f.raw.pool;put(expected,0,base_table);put(expected,0x64,0,4);reset_image(expected);const auto heaps=f.raw.heaps;
            f.docs.before_free=[&](auto p){check(word(f.raw.pool,0)==type_tables[k],"selected type table remains installed through block and array free callbacks");if(p==B::heap_address())check(!word(f.raw.pool,0x68)&&!word(f.raw.pool,0x70)&&!word(f.raw.pool,0x78)&&!word(f.raw.pool,0x64,4),"array free follows all three QWORD resets and loop completion");else check(word(f.raw.pool,0x64,4)==3-f.docs.entered_frees.size(),"block decrement precedes free callback");};
            f.direct();check(f.docs.completed_frees==std::vector<std::uintptr_t>{0x3333,0,0x1111,B::heap_address()},"all block entries including null freed LIFO before noninline array");check(f.raw.pool==expected&&f.raw.heaps==heaps,"destructor retains data pointer,capacity,stale entries and owned bytes after lower free identities");}
        {Fixture f(k);f.sentinel();put(f.raw.pool,8,0);f.docs.before_free=[&](auto p){check(!p&&word(f.raw.pool,0)==type_tables[k]&&!word(f.raw.pool,0x68)&&!word(f.raw.pool,0x70)&&!word(f.raw.pool,0x78),"null noninline array is freed after reset while type table is still installed");};f.destroy();check(f.docs.completed_frees==std::vector<std::uintptr_t>{0}&&word(f.raw.pool,0)==base_table&&!word(f.raw.pool,8),"no null guard or data-pointer reinitialization is invented");}
    }
}
void cached_entry_aliases(){
    for(unsigned k=0;k<4;++k){
        {Fixture f(k);f.raw.count(0,10);f.raw.regions={{B::pool_address,std::span(f.raw.pool).subspan(0x64,8)},{B::pool_address+8,std::span(f.raw.pool).subspan(8)}};f.raw.memory.regions=f.raw.regions;f.direct();
            check(f.docs.entered_frees.empty()&&f.raw.get(B::pool_address)==base_table&&word(f.raw.pool,0x64,4)==static_cast<std::uint32_t>(base_table)&&word(f.raw.pool,0x68)==1,"cached original zero skips block loop even when type-table store makes aliased count nonzero; final base store alias retained");}
        {Fixture f(k);std::array<std::uint8_t,16> alias{};alias[5]=1;put(f.raw.pool,8,B::heap_address());put(f.raw.heaps[2],0,0xa1a1);
            f.raw.regions={{B::pool_address,std::span(alias).first(8)},{B::pool_address+8,std::span(f.raw.pool).subspan(8,0x5c)},{B::pool_address+0x64,std::span(alias).subspan(5,4)},{B::pool_address+0x68,std::span(f.raw.pool).subspan(0x68)},{B::heap_address()-8,std::span(f.raw.heaps[2]).first(8)}};f.raw.memory.regions=f.raw.regions;
            f.docs.before_free=[&](auto p){if(p==0xa1a1)check(f.raw.get(B::pool_address+0x64,4)==0xffffffff,"type-table store makes live count0 but cached nonzero still enters loop and decrements toffffffff");};f.docs.after_free=[&](auto){f.raw.set(B::pool_address+0x64,0,4);};f.direct();
            check(f.docs.completed_frees==std::vector<std::uintptr_t>{0xa1a1,B::heap_address()}&&word(alias,0)==base_table,"cached nonzero entry uses live old0 index to free data-8 before array; final base store completes");}
    }
}
void live_mutations(){
    for(unsigned k=0;k<4;++k){
        {Fixture f(k);f.sentinel();f.raw.count(1,10);put(f.raw.pool,8,B::heap_address());put(f.raw.heaps[0],0,0xbaba);
            f.docs.after_free=[&](auto p){if(p==0xbaba){put(f.raw.pool,0,0x7777);put(f.raw.pool,8,B::heap_address(1));f.raw.count(2,23);put(f.raw.heaps[1],8,0xcaca);}else if(p==0xcaca)put(f.raw.pool,0x64,0,4);};f.docs.before_free=[&](auto p){if(p==B::heap_address(1))check(word(f.raw.pool,0)==0x7777&&!word(f.raw.pool,0x68)&&!word(f.raw.pool,0x70)&&!word(f.raw.pool,0x78),"lower custom vptr retained until array free and base-table store is last");};f.direct();
            check(f.docs.completed_frees==std::vector<std::uintptr_t>{0xbaba,0xcaca,B::heap_address(1)}&&word(f.raw.pool,8)==B::heap_address(1)&&word(f.raw.pool,0x60,4)==23&&word(f.raw.pool,0)==base_table,"loop uses live count/data mutations and final array pointer reread");}
        {Fixture f(k);f.raw.count(0xffffffff,10);put(f.raw.pool,8,B::heap_address());put(f.raw.heaps[2],0,0xfefe);f.raw.extras.push_back({B::heap_address()-16,std::span(f.raw.heaps[2]).first(8)});f.raw.refresh();f.docs.before_free=[&](auto p){if(p==0xfefe)check(word(f.raw.pool,0x64,4)==0xfffffffe,"raw negative count enters destructor loop and decrements before free");};f.docs.after_free=[&](auto p){if(p==0xfefe)put(f.raw.pool,0x64,0,4);};f.direct();check(f.docs.completed_frees==std::vector<std::uintptr_t>{0xfefe,B::heap_address()}&&word(f.raw.pool,0)==base_table,"negative loop terminates through explicit lower count mutation");}
        {Fixture f(k);put(f.raw.pool,0x68,B::heap_address());f.raw.regions={{B::pool_address,std::span(f.raw.pool).first(8)},{B::pool_address+8,std::span(f.raw.pool).subspan(0x68,8)},{B::pool_address+0x10,std::span(f.raw.pool).subspan(0x10)}};f.raw.memory.regions=f.raw.regions;f.direct();check(f.docs.completed_frees==std::vector<std::uintptr_t>{0}&&word(f.raw.pool,0)==base_table,"array pointer is loaded after reset when root/data share backing, so free receives live0");}
    }
}
void bounded_and_lower_failures(){
    for(unsigned k=0;k<4;++k){
        for(unsigned at:{0x64U,0U}){Fixture f(k);const auto expected=f.raw.pool;f.raw.omitted={{B::pool_address+at,at==0?8U:4U}};f.raw.refresh();unsupported([&]{f.direct();});check(f.raw.pool==expected&&f.docs.entered_frees.empty(),"missing entry count prevents vtable store; missing vtable prevents all loop actions");}
        for(unsigned at:{8U,0x10U}){Fixture f(k);f.sentinel();f.raw.count(1,10);auto expected=f.raw.pool;put(expected,0,type_tables[k]);put(expected,0x64,0,4);f.raw.omitted={{B::pool_address+at,8}};f.raw.refresh();unsupported([&]{f.direct();});check(f.raw.pool==expected&&f.docs.entered_frees.empty(),"missing data/slot retains initial type table and count decrement without resets");}
        {Fixture f(k);f.raw.count(1,10);f.raw.extras.push_back({B::inline_address,std::span(f.raw.heaps[3]).first(8)});f.raw.refresh();auto expected=f.raw.pool;put(expected,0,type_tables[k]);put(expected,0x64,0,4);unsupported([&]{f.direct();});check(f.raw.pool==expected,"ambiguous block slot fails after type store and committed decrement");}
        for(unsigned stop:{0x68U,0x70U,0x78U}){Fixture f(k);f.sentinel();auto expected=f.raw.pool;put(expected,0,type_tables[k]);for(unsigned at:{0x68U,0x70U,0x78U})if(at<stop)put(expected,at,0);f.raw.omitted={{B::pool_address+stop,8}};f.raw.refresh();unsupported([&]{f.direct();});check(f.raw.pool==expected&&f.docs.entered_frees.empty(),"QWORD reset failure keeps type table and completed zero-store prefix; no array free or base store");}
        {Fixture f(k);f.sentinel();f.raw.omitted={{B::pool_address+8,8}};f.raw.refresh();auto expected=f.raw.pool;put(expected,0,type_tables[k]);reset_image(expected);unsupported([&]{f.direct();});check(f.raw.pool==expected,"zero-count missing array pointer fails only after all resets and before final base store");}
        for(bool after:{false,true}){Fixture f(k);f.sentinel();f.raw.count(1,10);put(f.raw.pool,0x10,0x4545);auto expected=f.raw.pool;put(expected,0,type_tables[k]);put(expected,0x64,0,4);const auto hook=[](auto){throw Failure{77};};if(after)f.docs.after_free=hook;else f.docs.before_free=hook;failure([&]{f.direct();});check(f.raw.pool==expected&&f.docs.completed_frees.size()==(after?1U:0U),"block free failure retains decrement and type table but prevents resets/array free/base store");}
        for(bool after:{false,true}){Fixture f(k);f.sentinel();put(f.raw.pool,8,B::heap_address());auto expected=f.raw.pool;put(expected,0,type_tables[k]);reset_image(expected);const auto hook=[](auto){throw Failure{77};};if(after)f.docs.after_free=hook;else f.docs.before_free=hook;failure([&]{f.direct();});check(f.raw.pool==expected&&f.docs.completed_frees.size()==(after?1U:0U),"array free failure retains resets and stale data/capacity while preventing final base store");}
        for(bool ambiguous:{false,true}){Fixture f(k);f.sentinel();put(f.raw.pool,8,B::heap_address());auto expected=f.raw.pool;put(expected,0,type_tables[k]);reset_image(expected);f.docs.after_free=[&](auto){if(ambiguous)f.raw.extras.push_back({B::pool_address,std::span(f.raw.heaps[3]).first(8)});else f.raw.omitted={{B::pool_address,8}};f.raw.refresh();};unsupported([&]{f.direct();});check(f.raw.pool==expected&&f.docs.completed_frees==std::vector<std::uintptr_t>{B::heap_address()},"final base-table mapping failure retains completed array free and all prior state writes");}
    }
}
}
int main(){try{identity_and_lifo();cached_entry_aliases();live_mutations();bounded_and_lower_failures();std::cout<<"PASS: "<<checks<<" pool destructor core checks; four type/base identities,cached entry aliases both directions,LIFO/negative counts,live mutations,ordered resets,array free and exact failure prefixes; lower free/nativeABI/EH supplied\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected failure after "<<checks<<" checks\n";return 1;}}
